export const hexNotes=rows.split('\n').map(r=>{const [theme,note,question]=r.split('|');return {theme,note,question}});
export const lineNotes=['初爻对应事情的开端，适合检查基础、动机和进入条件。','二爻处在下卦中段，可借此观察日常行动、合作与承接。','三爻处在下卦末端，提示留意阶段转换、压力和行动边界。','四爻进入上卦，可借此观察外部环境、角色变化与协作。','五爻接近核心位置，可借此审视责任、影响和资源运用。','上爻处在一卦的末端，适合反思收束、退出与转化。'];
export const wordNotes=[['元亨','元有大、始之意，亨指通达；需结合具体卦辞理解。'],['利贞','指适宜守正、坚持正当的原则。'],['有孚','孚有诚信、可信之意。'],['无咎','咎指过失、责咎；无咎不是保证一切顺利。'],['利涉大川','渡越大河的意象，常用来表达承担重要行动。'],['利见大人','古语中指适宜求见有德、有位或能提供指引的人。'],['有攸往','指有所前往、开展行动。'],['取女','古语中的婚嫁表达，阅读时应注意时代语境。'],['利艰贞','处在艰难条件中，仍重视守正与坚持。'],['吉','古籍中的趋向性判断语，不代表现代事件的必然结果。'],['凶','古籍中的警示性判断语，不代表事情一定发生。']];
export function explainHex(code){const k=sequence(code),entry=hexNotes[k-1];return {code,number:k,name:names[k-1],title:titleFor(code),original:guaci[k-1],words:wordNotes.filter(([word])=>guaci[k-1].includes(word)).slice(0,4),...entry,upper:tri[code>>3],lower:tri[code&7]}}
